PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  type TEXT NOT NULL,
  payload TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE intents (
  idempotency_key TEXT PRIMARY KEY,
  symbol TEXT NOT NULL,
  action TEXT NOT NULL,
  side TEXT,
  level_index INTEGER,
  level_price REAL,
  volume REAL,
  reason TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'PENDING',
  broker_order_id TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  completed_at TEXT
);
CREATE TABLE kv (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE open_level_reservations (
  symbol TEXT NOT NULL,
  side TEXT NOT NULL,
  level_index INTEGER NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY(symbol, side, level_index)
);
CREATE TABLE positions (
  id TEXT PRIMARY KEY,
  symbol TEXT NOT NULL,
  side TEXT NOT NULL,
  level_index INTEGER NOT NULL,
  level_price REAL NOT NULL,
  entry_price REAL NOT NULL,
  volume REAL NOT NULL,
  status TEXT NOT NULL,
  opened_at TEXT NOT NULL,
  closed_at TEXT,
  close_price REAL,
  broker_order_id TEXT,
  pnl REAL,
  re_entry_count INTEGER NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX idx_active_level
ON positions(symbol, side, level_index)
WHERE status IN ('OPEN', 'PENDING');
CREATE INDEX idx_intents_created
ON intents(created_at DESC);
CREATE UNIQUE INDEX idx_open_level
ON positions(symbol, side, level_index, status)
WHERE status = 'OPEN';
CREATE INDEX idx_positions_opened
ON positions(opened_at DESC);
CREATE INDEX idx_positions_status_opened
ON positions(status, opened_at DESC);
COMMIT;
PRAGMA foreign_keys=ON;
